const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, PageOrientation, HighlightColor, VerticalAlign } = require("docx");
const fs = require("fs");

// Landscape US Letter: width/height swapped by docx-js when orientation LANDSCAPE, so pass portrait dims
const PAGE_SIZE = { width: 12240, height: 15840 };

function run(text, opts = {}) {
  return new TextRun({ text, size: 19, italics: !!opts.italics, bold: !!opts.bold, highlight: opts.hl ? "yellow" : undefined });
}

function cellPara(runs, opts = {}) {
  return new Paragraph({ spacing: { after: 100 }, children: Array.isArray(runs) ? runs : [run(runs, opts)] });
}

function sectionHeaderRow(title, colWidths) {
  return new TableRow({
    children: [
      new TableCell({
        columnSpan: 2,
        width: { size: colWidths[0] + colWidths[1], type: WidthType.DXA },
        shading: { type: ShadingType.CLEAR, fill: "2F2F2F" },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: title, bold: true, size: 22, color: "FFFFFF" })] })],
      }),
    ],
  });
}

function headerLabelsRow(colWidths) {
  return new TableRow({
    children: [
      new TableCell({
        width: { size: colWidths[0], type: WidthType.DXA },
        shading: { type: ShadingType.CLEAR, fill: "D9D9D9" },
        margins: { top: 60, bottom: 60, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "ORIGINAL SCRIPT", bold: true, size: 19 })] })],
      }),
      new TableCell({
        width: { size: colWidths[1], type: WidthType.DXA },
        shading: { type: ShadingType.CLEAR, fill: "D9D9D9" },
        margins: { top: 60, bottom: 60, left: 120, right: 120 },
        children: [new Paragraph({ children: [new TextRun({ text: "UPDATED SCRIPT (changes highlighted)", bold: true, size: 19 })] })],
      }),
    ],
  });
}

function row(label, leftParas, rightParas, colWidths) {
  return new TableRow({
    children: [
      new TableCell({
        width: { size: colWidths[0], type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        verticalAlign: VerticalAlign.TOP,
        children: [
          new Paragraph({ spacing: { after: 80 }, children: [new TextRun({ text: label, bold: true, size: 19, color: "555555" })] }),
          ...leftParas,
        ],
      }),
      new TableCell({
        width: { size: colWidths[1], type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 120, right: 120 },
        verticalAlign: VerticalAlign.TOP,
        children: [
          new Paragraph({ spacing: { after: 80 }, children: [new TextRun({ text: label, bold: true, size: 19, color: "555555" })] }),
          ...rightParas,
        ],
      }),
    ],
  });
}

const COLW = [6300, 6300]; // total ~12600 dxa fits landscape letter with margins

/* ============================= DEMO SCRIPT TABLE ============================= */

const demoRows = [
  sectionHeaderRow("DEMO SCRIPT — Med Spa Growth Strategy Session", COLW),
  headerLabelsRow(COLW),

  row(
    "Introduction",
    [
      cellPara("Hey {{Name}}, great to see you again. Last time we spoke we discussed your goal of {{Desired Outcome}} and some of the challenges currently preventing the practice from getting there. Today we're going to go much deeper. I'll ask a few more questions so I have a complete picture of your practice, then I'll walk you through exactly what I'd focus on if this were my own med spa. By the end of today you'll know what's limiting growth, where revenue is leaking, what I'd prioritize first, and whether we're the right fit to help implement it. Sound good?"),
    ],
    [
      cellPara("Hey {{Name}}, great to see you again. Last time we spoke we discussed your goal of {{Desired Outcome}} and some of the challenges currently preventing the practice from getting there. Today we're going to go much deeper. I'll ask a few more questions so I have a complete picture of your practice, then I'll walk you through exactly what I'd focus on if this were my own med spa. By the end of today you'll know what's limiting growth, where revenue is leaking, what I'd prioritize first, and whether we're the right fit to help implement it. Sound good?"),
      cellPara([
        run("Before we dive in, I'll mention this because it matters for the conversation we're about to have. Bethany has spent over two decades working inside med spas and aesthetic practices in nearly every role there is, front desk, injector support, operations, sales, and running a multi-location practice herself. So everything we walk through today isn't theory. It's built from having done this work from the inside.", { hl: true }),
      ]),
    ],
    COLW
  ),

  row(
    "Discovery, Pain & Impact, Current Solutions, Future Pace",
    [cellPara("No changes. Full Q1 to Q18 discovery, pain and impact, current solutions, and future pace sections remain exactly as written.", { italics: true })],
    [cellPara("No changes. Full Q1 to Q18 discovery, pain and impact, current solutions, and future pace sections remain exactly as written.", { italics: true })],
    COLW
  ),

  row(
    "Pitch Intro",
    [cellPara("Before I explain the plan, it's important to understand something. Most med spas think they need more leads. Very rarely is that actually the problem. Almost every established clinic we work with already has enough opportunity to grow significantly. What's missing is the system that turns more of those opportunities into long-term revenue. That's what we build. Everything we do fits into four stages. I'll walk through each one and then you can decide if it makes sense for your clinic. Sound good?")],
    [cellPara("Before I explain the plan, it's important to understand something. Most med spas think they need more leads. Very rarely is that actually the problem. Almost every established clinic we work with already has enough opportunity to grow significantly. What's missing is the system that turns more of those opportunities into long-term revenue. That's what we build. Everything we do fits into four stages. I'll walk through each one and then you can decide if it makes sense for your clinic. Sound good?")],
    COLW
  ),

  row(
    "STEP 1 - Increase Patient Consultations",
    [
      cellPara("The first thing we do is identify where patient demand is being lost. That includes lead generation, speed to lead, follow up, booking systems, automation and marketing channels. Because if patients aren't consistently booking consultations, nothing else matters."),
      cellPara("For your clinic specifically: {{Personalize}}"),
      cellPara("Example: Right now you're generating inquiries, but follow up isn't consistent enough to maximize consultation volume. That's where we'd begin.", { italics: true }),
      cellPara("Proof: One practice came to us generating around $65,000 per month. After improving lead response, qualification and booking systems, they significantly increased consultation volume and unlocked more revenue without increasing ad spend.", { italics: true }),
      cellPara("Does that make sense? Can you see why this has to be the first step?"),
    ],
    [
      cellPara("The first thing we do is identify where patient demand is being lost. That includes lead generation, speed to lead, follow up, booking systems, automation and marketing channels. Because if patients aren't consistently booking consultations, nothing else matters."),
      cellPara([
        run("Before we ever pull the marketing trigger, we start with a Revenue Leak Audit and a Market Blueprint specific to your practice. This is what separates us from a typical agency. Most agencies start spending your money before they understand your market or where you're actually losing revenue. We map that first, so every dollar you invest afterward is going toward what your specific market and your specific practice actually needs. It saves you money, it removes the guesswork, and it's a big part of why clinics see us as a growth partner and not just another vendor.", { hl: true }),
      ]),
      cellPara("For your clinic specifically: {{Personalize}}"),
      cellPara("Example: Right now you're generating inquiries, but follow up isn't consistent enough to maximize consultation volume. That's where we'd begin.", { italics: true }),
      cellPara("Proof: One practice came to us generating around $65,000 per month. After improving lead response, qualification and booking systems, they significantly increased consultation volume and unlocked more revenue without increasing ad spend.", { italics: true }),
      cellPara("Does that make sense? Can you see why this has to be the first step?"),
    ],
    COLW
