    "STEP 2 to STEP 4, Transition, Offer, Guarantee, Close, L.E.A.D.",
    [cellPara("No changes. Conversion, lifetime value, systems steps, transition, offer, guarantee, close and objection framework remain exactly as written.", { italics: true })],
    [cellPara("No changes. Conversion, lifetime value, systems steps, transition, offer, guarantee, close and objection framework remain exactly as written.", { italics: true })],
    COLW
  ),
];

const demoTable = new Table({
  width: { size: COLW[0] + COLW[1], type: WidthType.DXA },
  columnWidths: COLW,
  rows: demoRows,
});

/* ============================= TRIAGE SCRIPT TABLE ============================= */

const triageRows = [
  sectionHeaderRow("TRIAGE SCRIPT — Med Spa Growth Assessment", COLW),
  headerLabelsRow(COLW),

  row(
    "Opener, Sections 1 to 5 (Goals, Business, Bottleneck, Financial Impact, Summarize)",
    [cellPara("No changes. Opener and Sections 1 through 5 remain exactly as written.", { italics: true })],
    [cellPara("No changes. Opener and Sections 1 through 5 remain exactly as written.", { italics: true })],
    COLW
  ),

  row(
    'Section 6, Bridge To Strategy Session — "What exactly do you guys do?"',
    [
      cellPara("We help established med spas grow by optimizing the entire patient journey, not just marketing. That includes patient acquisition, lead response, consultation conversion, retention, memberships, reactivation, automation, reporting, and operational systems. Most clinics think they need more leads, but we usually find they're losing significant revenue from the opportunities they already have. Our job is to identify those bottlenecks and implement the systems that create predictable, profitable growth."),
    ],
    [
      cellPara("We help established med spas grow by optimizing the entire patient journey, not just marketing. That includes patient acquisition, lead response, consultation conversion, retention, memberships, reactivation, automation, reporting, and operational systems."),
