    "Section 7, Book Strategy Session and Post-Call Follow-Up",
    [cellPara("No changes. Booking section and post-call follow-up message remain exactly as written.", { italics: true })],
    [cellPara("No changes. Booking section and post-call follow-up message remain exactly as written.", { italics: true })],
    COLW
  ),
];

const triageTable = new Table({
  width: { size: COLW[0] + COLW[1], type: WidthType.DXA },
  columnWidths: COLW,
  rows: triageRows,
});

const doc = new Document({
  sections: [
    {
      properties: {
        page: {
          size: PAGE_SIZE,
          orientation: PageOrientation.LANDSCAPE,
          margin: { top: 700, bottom: 700, left: 600, right: 600 },
        },
      },
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 100 },
          children: [new TextRun({ text: "The Luxora Collective — Script Changes: Original vs. Updated", bold: true, size: 30 })],
        }),
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { after: 300 },
          children: [new TextRun({ text: "Highlighted text marks what was added. Everything else is unchanged.", italics: true, size: 19, color: "555555" })],
        }),
        demoTable,
        new Paragraph({ text: "", spacing: { before: 400, after: 400 } }),
        triageTable,
      ],
    },
  ],
});

(async () => {
  const buf = await Packer.toBuffer(doc);
  fs.writeFileSync("/home/claude/Luxora_Scripts_Comparison.docx", buf);
  console.log("done");
})();

